        >
          <Button variant="ghost" size="icon" className="size-8 rounded-full hover:bg-muted">
            <Share className="size-4 stroke-[1.5]" />
          </Button>
        </ExportModal>
        {sharh && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setShowSharh(!showSharh)}
            className="text-muted-foreground hover:text-foreground gap-1"
          >
            الشرح
